export class AIController {
    /**
     * Map of AI agents by key (bodyType_bodyIndex).
     * @type {Map<string, AIAgentData>}
     * @private
     */
    private _agents;
    /**
     * Get a physics body by index and type.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type ('dynamic' or 'kinematic').
     * @returns {Object|null} Body object or null.
     * @private
     */
    private _getBody;
    /**
     * Get an agent controller by index and type.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {Object|null} Agent controller or null.
     * @private
     */
    private _getAgentController;
    /**
     * Create a key for agent lookup.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {string} Lookup key.
     * @private
     */
    private _getKey;
    /**
     * Get or create AI data for an agent.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {AIAgentData} Agent AI data.
     * @private
     */
    private _getOrCreateAgent;
    /**
     * Update AI configuration for an agent.
     * Called when main thread sends configuration updates.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @param {Object} config - Configuration updates.
     */
    updateAgent(bodyIndex: number, bodyType: string, config: any): void;
    /**
     * Check if an agent has AI enabled.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {boolean} True if AI is enabled.
     */
    isEnabled(bodyIndex: number, bodyType: string): boolean;
    /**
     * Get the current intent for an agent.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {AgentIntent|null} Current intent or null.
     */
    getCurrentIntent(bodyIndex: number, bodyType: string): AgentIntent | null;
    /**
     * Get the active intent name for an agent.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {string} Active intent name or 'idle'.
     */
    getActiveIntentName(bodyIndex: number, bodyType: string): string;
    /**
     * Record damage for an agent's damage sensor.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @param {Object} hitData - Hit information.
     * @param {Object} body - The physics body.
     */
    recordDamage(bodyIndex: number, bodyType: string, hitData: any, body: any): void;
    /**
     * Update all AI agents.
     * Called each physics frame.
     *
     * @param {number} delta - Time delta in seconds.
     */
    update(delta: number): void;
    /**
     * Remove an agent.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     */
    removeAgent(bodyIndex: number, bodyType: string): void;
    /**
     * Clear all agents.
     */
    clear(): void;
    /**
     * Get debug info for an agent.
     *
     * @param {number} bodyIndex - Body index.
     * @param {string} bodyType - Body type.
     * @returns {Object|null} Debug information.
     */
    getDebugInfo(bodyIndex: number, bodyType: string): any | null;
}
/**
 * Singleton instance of AIController.
 * @type {AIController}
 */
export const aiController: AIController;
